import{_ as i,a0 as l,w as a,s as M,ao as u,I as n,x as p,a1 as t,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"戴文的Linux內核專題：08 配置內核(4) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：08 配置內核(4) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：08 配置內核(4) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：08 配置內核(4) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/08 The Linux Kernel--Configuring the Kernel Part 4","title":"戴文的Linux內核專題：08 配置內核(4)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/08 The Linux Kernel--Configuring the Kernel Part 4.md","filePath":"[post].md"}'),s={name:"The Linux Kernel/08 The Linux Kernel--Configuring the Kernel Part 4.md"};function m(A,e,C,T,_,E){const o=l("Link");return a(),M("div",null,[e[11]||(e[11]=u('<h1 id="戴文的linux內核專題-08-配置內核-4" tabindex="-1">戴文的Linux內核專題：08 配置內核(4) <a class="header-anchor" href="#戴文的linux內核專題-08-配置內核-4" aria-label="Permalink to “戴文的Linux內核專題：08 配置內核(4)”">​</a></h1><p>在這個第四部分裏，我們將繼續配置更多的設置和特性。</p><p>這裏我們被問及關於&quot;IBM Calgary IOMMU support (CALGARY_IOMMU)&quot;。這個選項將會提供對IBM xSeries x366和x460的IOMMU的支持。這也將讓那些32位PCI的設備工作正常——在這些系統上不支持雙地址週期(DAC : Double Address Cycle)——因為該系統設置在訪問超過3GB內存的時候會有問題。如果需要這些IOMMU設備可以用&quot;iommu=off&quot;在啓動時關閉。(這些內核/模組參數會在以後的文章中討論)</p><p>IOMMU(input/output memory management unit)是一個內存管理單元(MMU)，它連接具有DMA功能的I/O總線到主內存上。DMA(Direct Memory Access)是許多計算機支持的一種允許特定設備不借助CPU直接訪問內存的特性。雙地址週期(Double Address Cycle, DAC)是64位DMA；而通常的DMA使用32位。</p><p>下面，我們被問及是否默認啓用Calgary(Should Calgary be enabled by default? (CALGARY_IOMMU_ENABLED_BY_DEFAULT))。Calgary與上面提到的IOMMU是同一個概念。這兩者之間的不同是IOMMU可以支持許多設備而Calgary只能支持IBM IOMMU設備。如果禁用了它，但是以後需要使用到它，可以使用內核參數(iommu=calgary)。</p><p>這裏有個問題需要小心處理(Enable Maximum number of SMP Processors and NUMA Nodes (MAXSMP))。只有在內核運行在擁有很多SMP處理器和NUMA節點的情況下才啓用它，如Core i7和許多AMD CPU芯片。如果系統缺乏或者只有少量的SMP處理器和NUMA節點，內核就會變得低效。這個最好選擇&quot;No&quot;。</p><p>非一致性內存訪問(Non-Uniform Memory Access (NUMA))是一個每塊內存都需要花費更長時間訪問其他部分內存的系統。一個節點就是一組內存。例如，一個NUMA系統可能有三塊內存芯片。每塊芯片是一個節點，在帶CPU的主板上有一個節點/芯片(這是最快的節點)，另外兩個在不同的總線上。這兩個節點需要比第一個節點花費更長的時間去訪問。</p><p>注意：ccNUMA和NUMA目前是一樣的，至少是非常相似的。</p><p>對稱多處理器(Symmetric Multi-Processing (SMP))是NUMA的替代品。它的內存在同一根總線上。只有限定數量的CPU可以訪問總線，所以這限制了SMP系統上處理器的數量。然而它內存的訪問速度一樣塊。</p><p>注意：我是在為AMD64系統在編譯內核，所以我會告訴你我的選擇，來幫助讀者理解過程和選擇。如果我沒有指出我的選擇，那麼我用的就是默認選擇。如果你在為不同的系統編譯或者你有不同的需求，你需要在你的情況下做出替代的選擇。</p><p>接下來，除非配置工具已經為你做了選擇，選擇一個內核需要支持的最多CPU的數量。這個配置根據你給的數量優化內核。</p><p>接着啓用或禁用&quot;SMT (Hyperthreading) scheduler support (SCHED_SMT)&quot;（超線程調度器支持）。SMT調度器提升了在使用了超線程技術的Pentium 4處理器上的CPU決策能力。然而，這會帶來額外的功耗，在一些系統上最好像我一樣選擇&quot;no&quot;。</p><p>超線程一種專有的SMT並行微處理器(Intel 實現了它)。這是多任務/多線程(同時做許多任務)的一種特殊形式，並行多線程(Simultaneous multithreading (SMT))提升了多線程執行的效率。</p><p>在這之後，啓用或者禁用&quot;Multi-core scheduler support (SCHED_MC)&quot;。這樣也是一種提升多核CPU決策的特性。然而這回帶來額外功耗，我選擇了&quot;No&quot;。</p><p>在下一個選項中可以選擇搶佔模式。</p><p>Preemption Model（搶佔模式）</p><p>1. No Forced Preemption (Server) (PREEMPT_NONE) （非強制搶佔）</p><p>&gt; 2. Voluntary Kernel Preemption (Desktop) (PREEMPT_VOLUNTARY) （自願內核搶佔）</p><p>3. Preemptible Kernel (Low-Latency Desktop) (PREEMPT) （可搶佔內核）</p><p>choice[1-3]: 2</p><p>搶佔就是暫停一個意圖讓它之後繼續執行的中斷任務的過程。搶佔強制一個進程暫停，執行中的任務無法忽視搶佔。</p><p>接着，我們被詢問關於&quot;Reroute for broken boot IRQs (X86_REROUTE_FOR_BROKEN_BOOT_IRQS)&quot;。這是一個對於假中斷的簡單修復。假中斷是一種無用的硬件中斷，這些通常是有電子干擾或者錯誤連接的電子產品觸發。記住，中斷是發送給處理器需要馬上注意的信號。</p><p>這個選項對任何機器都很重要；我懷疑任何人可能都會有禁用這個特性的理由(Machine Check / overheating reporting (X86_MCE))。內核必須意識到過熱和數據損壞，不然，系統將會繼續操作，這樣只會導致進一步的破壞。</p><p>下面，用户可以啓用禁用&quot;Intel MCE features (X86_MCE_INTEL)&quot;，這是一種額外的對像熱度監控的Intel MCE特性的支持。因為我是為AMD64處理器編譯內核所以我選擇了&quot;no&quot;。機器檢測異常(MCE)是一種當處理器發現硬件問題時的錯誤輸出。MCE通常會導致內核嚴重錯誤(kernel panic)(相當於Windows中的&quot;藍屏&quot;)。</p><p>這個除了是AMD設備外是同一個問題Intel MCE features (X86_MCE_INTEL)。</p><p>下一個是我會禁用的調試特性(Machine check injector support (X86_MCE_INJECT))。這個會允許注射檢查。如果你偶爾執行機器注射，那最好編譯成模組而不是編譯進內核。機器注射可以使設備即使實際沒有錯誤也可以發送一個偽造的錯誤信息。這個用來確認內核和其他進程可以正常處理錯誤。比如，如果CPU過熱，接着應該關機，但是開發者如何在不損壞CPU的情況下測試代碼。注射錯誤是一種最好的方法，因為它只是一種告訴硬件發送錯誤信號的軟件。</p><p>注:模組是對可能被使用或者很少執行的特性/驅動而言的。只加入在許多使用該內核的系統中用到的特性/驅動到內核中。</p><p>如果內核很可能用在Dell筆記本上，那麼啓用這個特性(Dell laptop support (I8K))。否則，如果一些用户可能在戴爾筆記本電腦上用到這個內核，將其作為一個模組加入。如果這個內核不打算支持Dell筆記本，那就像我一樣忽略掉它。特別地，這個支持是一個允許Dell Inspiron 8000系列筆記本訪問處理器的系統管理模式的驅動。系統管理模式的目的是得到處理器的温度和風扇狀態，這對一些需要控制風扇的系統有用。</p><p>下面，用户可以選擇微碼加載支持(CPU microcode loading support (MICROCODE))。這可以允許用户在支持這個特性的AMD或者Intel芯片上更新微碼。</p><p>注意：為了加載微碼，你必須擁有一個為你的處理器設計的合法的二進制微代碼拷貝。</p><p>如果要加載微碼補丁(修復bug或加入次要的特性)到intel芯片上(Intel microcode loading support (MICROCODE_INTEL))，這個就必須啓用。這裏我禁用了它。</p><p>然後是AMD芯片的類似選項(AMD microcode loading support (MICROCODE_AMD))。</p><p>啓用這個支持(/dev/cpu/*/msr - Model-specific register support (X86_MSR))可以允許某個處理器有權限使用x86特殊模組寄存器(Model-Specific Registers (MSRs))。這些寄存器是一些字符設備，包括major 202下minor 0到31的設備((/dev/cpu/0/msr to /dev/cpu/31/msr))。這個特性用在多處理器系統上。每個虛擬字符設備都連接到一個特定的CPU。</p><p>注意：MSRs被用來改變CPU設備、調試、性能監控和執行追蹤。MSRs使用x86指令集。</p><p>在這之後，我們有一個選項&quot;CPU information support (X86_CPUID)&quot;，啓用這個特性允許處理器訪問x86 CPUID指令，這需要通過字符設備在一個特定的CPU上執行。這些字符設備包括major 202下minor 0到31的設備(/dev/cpu/0/msr to /dev/cpu/31/msr)，就像上面x86_MSR支持的這些。</p><p>如果處理器支持，啓用內核線性映射來使用1GB的內存頁(Enable 1GB pages for kernel pagetables (DIRECT_GBPAGES))。啓用這個可以幫助減輕TLB的壓力。</p><p>頁是內存本身的基本單位(位是數據的基本單位)。頁的大小是由硬件自身決定的。頁碼錶是虛擬和物理內存間的映射。物理內存是設備上的內存。虛擬內存是到內存的地址。依賴於系統架構，硬件可以訪問大於實際內存地址的地址。舉例來説，一個64位系統擁有6GB內存，管理員在需要時可以加上更多的內存。這是因為還有很多虛擬內存地址。然而，在很多32位系統上，系統管理員可以增加一條8GB的內存，但是系統無法完全使用它，因為系統中沒有足夠的虛擬內存地址去訪問大容量的內存。轉換後援緩衝器(Translation Lookaside Buffer (TLB))是一種提升虛擬內存轉換速度的緩存系統。</p><p>下面，我們看到了NUMA選項(Numa Memory Allocation and Scheduler Support (NUMA))。這可以允許內核在CPU本地內存分配器上分配CPU可使用的內存。這個支持同樣可使內核更好感知到NUMA。很少的32位系統需要這個特性，但是一些通用的645位處理器使用這個特性。我選擇了&quot;no&quot;。</p><p>為了系統使用舊方式來檢測AMD NUMA節點拓撲，啓用這個特性(Old style AMD Opteron NUMA detection (AMD_NUMA))。下一個選項是一種更新的檢測方式(ACPI NUMA detection (X86_64_ACPI_NUMA))。如果兩個都啓用，新的方式將會佔支配作用。一些硬件在使用其中一種方式而不是另外一個時工作得更好。</p><p>如果為了調試目的的NUMA仿真，可以啓用下一個特性(NUMA emulation (NUMA_EMU))。</p><p>注意：如果你不打算進行調試並且你需要一個快速、輕量級系統，那麼禁用盡可能多的調試特性。</p><p>下一個選項中，選擇你的內核打算如何處理NUMA節點的最大數量。接下來選擇內存模型，這裏可能只有一個內存模型選擇。內存模型指定了內存如何存儲。</p><p>Maximum NUMA Nodes (as a power of 2) (NODES_SHIFT) [6]</p><p>Memory model</p><p>&gt; 1. Sparse Memory (SPARSEMEM_MANUAL)</p><p>choice[1]: 1</p><p>為了提升性能，這裏有一個選項用通過虛擬內存映射(Sparse Memory virtual memmap (SPARSEMEM_VMEMMAP))來優化pfn_to_page和page_to_pfn操作。頁幀號是每頁被給定的號碼。這兩個操作用來從號碼得到頁或者從頁得到號碼。</p><p>下一個選項是允許一個節點可以移除內存(Enable to assign a node which has only movable memory (MOVABLE_NODE))。內核頁通常無法移除。當啓用後，用户可以熱插拔內存節點，同樣可移除內存允許內存整理。作為出入內存的數據，只要有可用空間一組數據可能被劃分到不同內存。</p><p>接着前面的內存問題，我們還有更多的問題。這些可能已被配置工具預配置了。第三個選項(BALLOON_COMPACTION)，當啓用時可以幫助減少內存碎片。碎片內存會減慢系統速度。第四個選項(COMPACTION)允許內存壓縮。下面列到的第五個選項(MIGRATION)允許頁面被移動。</p><ul><li>Allow for memory hot-add (MEMORY_HOTPLUG) (允許內存熱添加)</li><li>Allow for memory hot remove (MEMORY_HOTREMOVE) （允許內存熱移除）</li><li>Allow for balloon memory compaction/migration (BALLOON_COMPACTION) （允許泡狀內存規整和合並）</li><li>Allow for memory compaction (允許內存規整)</li><li>Page migration (MIGRATION) (頁合併)</li></ul><p>注意：啓用可移動內存會啓用以上5個特性。</p><p>下一步，我們可以&quot;Enable KSM for page merging (KSM)&quot;。內核同頁合併(Kernel Samepage Merging (KSM))會查看程序認為可以合併的內核。如果兩頁內存完全相同這可以節約內存。一塊內存可以被刪除或者被合併，並且只有一塊可以使用。</p><p>配置工具可能會自動選擇保存多少內存用於用户分配(Low address space to protect from user allocation (DEFAULT_MMAP_MIN_ADDR) [65536])。</p><p>下一個選項很重要(Enable recovery from hardware memory errors (MEMORY_FAILURE))。如果內存故障並且系統有MCA恢復或者ECC內存，系統就可以繼續運行並且恢復。要使用這個特性，硬件自身和內核都必須支持。</p><p>機器檢測架構(Machine Check Architecture (MCA))是一個一些CPU上可以發送硬件錯誤信息給操作系統的特性。錯誤更正碼內存(Error-correcting code memory (ECC memory))是一種內存設備檢測和糾正錯誤的形式。</p><p>下面，配置工具會自動啓用&quot;HWPoison pages injector (HWPOISON_INJECT)&quot;。這個特性允許內核標記一塊壞頁為&quot;poisoned&quot;，接着內核會殺死創建壞頁的程序。這有助於停止並糾正錯誤。</p><p>為了允許內核使用大頁(Transparent Hugepage Support (TRANSPARENT_HUGEPAGE))，啓用這個特性。這可以加速系統但是需要更多內存。嵌入式系統不必使用這個特性。嵌入式系統通常只有非常小的內存。</p><p>如果啓用了上面的，那麼必須配置大頁的sysfs支持。</p><p>Transparent Hugepage Support sysfs defaults</p><p>1. always (TRANSPARENT_HUGEPAGE_ALWAYS)</p><p>&gt; 2. madvise (TRANSPARENT_HUGEPAGE_MADVISE)</p><p>choice[1-2?]: 2</p><p>下面的選項是增加process_vm_readv和process_vm_writev這兩個系統調用(Cross Memory Support (CROSS_MEMORY_ATTACH))。這允許特權進程訪問另外一個程序的地址空間。</p><p>如果有tmem，啓用緩存清理(cleancache)通常是一個好主意 (Enable cleancache driver to cache clean pages if Transcendent Memory (tmem) is present (CLEANCACHE))。當一些內存頁需要從內存中移除時，cleancache會將頁面放在cleancache-enabled的文件系統上。當需要該頁時，頁會被重新放回內存中。超內存(tmem)沒有一組已知大小的內存，內核對此內存使用間接尋址。</p><p>下一個選項允許在tmen激活後緩存交換頁(Enable frontswap to cache swap pages if tmem is present (FRONTSWAP))。frontswap在交換分區放置數據。交換特性的支持需要這個。</p><p>最好啓用下一個特性(Check for low memory corruption (X86_CHECK_BIOS_CORRUPTION))。這會檢測低位內存的內存損壞情況。這個特性在執行期被禁止。為了啓用這個特性,在內核命令列內加入 &quot;memory_corruption_check=1&quot;(這會在以後的文章中討論;這不同於任何命令列)。即使經常執行這個特性，也只使用非常小的開銷(接近沒有)。</p><p>接下來我門可以設置內存損壞檢測的默認設置(“Set the default setting of memory_corruption_check (X86_BOOTPARAM_MEMORY_CORRUPTION_CHECK))。這可以選擇是否開啓或關閉memory_corruption_check。最好啓用內存損壞檢測不然如果一部分重要內存損壞後可能會導致數據丟失和系統崩潰。</p><p>這個選項關注的是BIOS(Amount of low memory, in kilobytes, to reserve for the BIOS (X86_RESERVE_LOW) [64])。配置工具通常知道給BIOS預留內存的最佳大小。</p><p>對於Intel P6處理器，開發者可以啓用存儲區域類型寄存器(MTRR (Memory Type Range Register) support (MTRR))。這用於連接着VGA卡的AGP和PCI卡。啓用這個特性內核會創建/proc/mtrr。</p><p>如果X驅動需要加入回寫入口，那麼啓用下面的選項(MTRR cleanup support (MTRR_SANITIZER))。這會將MTRR的佈局從連續轉換到離散。存儲區域類型寄存器(Memory type range registers (MTRRs))提供了一種軟件訪問CPU緩存的方法。</p><p>下面，配置工具已經設置了一些MTRR選項</p><ul><li><p>MTRR cleanup enable value (0-1) (MTRR_SANITIZER_ENABLE_DEFAULT) [1]</p></li><li><p>MTRR cleanup spare reg num (0-7) (MTRR_SANITIZER_SPARE_REG_NR_DEFAULT) [1]</p></li></ul><p>為了設置頁級緩衝控制，那就啓用PAT屬性(x86 PAT support (X86_PAT))。頁屬性表(Page Attribute Table (PATs))是現在版的MTRRs並比它更靈活。如果你經歷過因啓用它而引發的啓動問題，那麼禁用這個特性後重新編譯內核。我選擇了&quot;no&quot;。</p><hr>',74)),n("p",null,[e[1]||(e[1]=p("via: ",-1)),t(o,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-4.4392/"},{default:r(()=>[...e[0]||(e[0]=[p("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-4.4392/",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=p("譯者：",-1)),t(o,{href:"https://github.com/geekpi"},{default:r(()=>[...e[2]||(e[2]=[p("geekpi",-1)])]),_:1}),e[5]||(e[5]=p(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=p("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原創翻譯，",-1)),t(o,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[p("Linux中國",-1)])]),_:1}),e[10]||(e[10]=p(" 榮譽推出",-1))])])}const d=i(s,[["render",m]]);export{R as __pageData,d as default};
